INSERT INTO `dc_barbarian_passives` (`passive_name`, `unlock_level`, `full_text`) VALUES
('Pound of Flesh', 10, 'When you are healed by a health globe, gain 2% Life regeneration per second and 4% increased movement speed for 15 seconds. This bonus stacks up to 5 times. | Unlocked at level 10. | "When the sky bleeds, the crops grow tall. When our enemies bleed, we grow strong." —Chant of the Harvest'),
('Ruthless', 10, 'You deal 40% additional damage to enemies below 30% health. | Unlocked at level 10. | The clans each paint their warriors in their own unique way. Some celebrate the mountain, others honor the fire, but the Targos clan worships the purifying virtue of pain.'),
('Nerves of Steel', 13, 'Fatal damage instead reduces you to 15% Life. For 3 seconds afterward, you take 95% reduced damage and are immune to all control-impairing effects. | This effect may occur once every 60 seconds. | Unlocked at level 13. | "The trials begin with childhood; skinning ferocious beasts, climbing windswept cliffs and carrying weapons heavy enough to make a southern soldier weep. Is it any wonder that they never give ground?" —Sir Aric of Duncraig'),
('Weapons Master', 16, 'Gain a bonus based on the weapon type of your main hand weapon: | Swords/Daggers: 8% increased damage | Maces/Axes: 5% Critical Hit Chance | Polearms/Spears: 8% attack speed | Mighty Weapons: 2 Fury per hit | Unlocked at level 16. | "My men ambushed the traveler in the woods, but it was we who were surprised. Such keen senses, swift motions, flawless strikes. We never stood a chance." —Redjack the Bandit'),
('Inspiring Presence', 20, 'The duration of your shouts is doubled. After using a shout you and all allies within 100 yards regenerate 3% of maximum Life per second for 120 seconds. | Your shouts are: | Battle Rage | Threatening Shout | War Cry | Unlocked at level 20. | "The enemy poured through the gap until Warmaster Karja impaled three demons at once on our battle standard, tossing their corpses into the fray below as she roared a rallying call from high atop the battlements." —The Battle of the Starless Night'),
('Berserker Rage', 20, 'You deal 25% additional damage while near maximum Fury. | Unlocked at level 20. | "You wouldn''t like me when I''m angry." —Bannar the Berserker'),
('Bloodthirst', 24, 'Each point of Fury spent heals you for 966 Life. | Heal amount is increased by 1% of your Health Globe Healing Bonus. | Unlocked at level 24. | "Compassion is weakness. To press the advantage when an opponent calls for mercy is the way of true power." —Halaberd the Conqueror'),
('Animosity', 27, 'Increase all Fury generation by 10%. | Increase maximum Fury by 20. | Fury is used to fuel your most powerful attacks. | Unlocked at level 27. | "While most orders teach the merits of calming the seas of the soul, the guardians of Arreat have embraced the raging inner storm." —Chronicler Arlavoc'),
('Superstition', 30, 'Reduce all non-Physical damage by 20%. When you take damage from a ranged or elemental attack, you have a chance to gain 2 Fury. | Unlocked at level 30. | "The sorcery of the west has brought us nothing but blight. Strength built these walls, and strength will hold them." —Gruchac Hammerhand'),
('Tough as Nails', 30, 'Increase Armor by 25%. | Increase Thorns by 100%. | Unlocked at level 30. | After a while the scars serve as their own layer of armor.'),
('No Escape', 35, 'Increase the damage of Weapon Throw, Seismic Slam, Ancient Spear, and Avalanche by 30% against enemies more than 15 yards away from you. | Unlocked at level 35. | "Run if you must, but you''ll only die tired." —Ooron Goons'),
('Relentless', 40, 'While below 35% Life, all skills cost 50% less Fury, Life per Fury Spent is doubled, and all damage taken is reduced by 50%. | Unlocked at level 40. | No matter the odds, some warriors simply refuse to fall.'),
('Brawler', 45, 'As long as there are 3 enemies within 12 yards, all of your damage is increased by 20%. | Unlocked at level 45. | "I have two blades, one for each of you." —Blademaster Kharne'),
('Juggernaut', 50, 'The duration of control-impairing effects on you are reduced by 50%. In addition, whenever a Stun, Freeze, Fear, or Immobilize is cast on you, you have a chance to recover 20% of your maximum Life. | Unlocked at level 50. | "I swear to you, we put a dozen arrows into him and he just stood back up. These so-called barbarians, these madmen of the north—there is no stopping them." —Soldier of Bastion''s Keep'),
('Unforgiving', 55, 'You no longer degenerate Fury. Instead, you generate 2 Fury every 1 second. | Unlocked at level 55. | "It was as if he suddenly came to know every grievous injury endured by his ancestors, and he had selected that very moment to exact their collective revenge." —Chronicler Arlavoc'),
('Boon of Bul-Kathos', 60, 'Reduce the cooldowns of your: | Earthquake by 15 seconds. | Call of the Ancients by 30 seconds. | Wrath of the Berserker by 30 seconds. | Unlocked at level 60. | The aid of the Immortal King shall come to those who have earned it.'),
('Earthen Might', 64, 'Gain 30 Fury when Avalanche or Earthquake is triggered. | Unlocked at level 64. | "My capital has become the cell in which I await my execution. The ground roars beneath me, announcing the presence of the wild men, as they rend and tear the foundations of the world and laugh. Oh, woe is me that I ever confused their savage ways for weakness."—Loren, Panep of Samauren'),
('Sword and Board', 66, 'While wielding a shield, reduce all damage taken by 30% and reduce Fury costs by 20%. | Unlocked at level 66. | "Turning away the attack of an enemy saps their resolve as surely as landing a blow of your own." —Battlemaster Kal-Jor'),
('Rampage', 68, 'Increase Strength by 1% for 8 seconds after killing or assisting in killing an enemy. This effect stacks up to 25 times. | Unlocked at level 68. | "The battle was never ending, sapping our minds and bodies to the point of exhaustion. But they thrived amidst the carnage, every killing blow renewing their bloodlust. They couldn''t be stopped." —Sergeant Peshkov on the Siege of the Barbarians, 1123 Anno Kehjistani');
